import{_ as a,o as i,c as t,a2 as e}from"./chunks/framework.BvlN9b-o.js";const c=JSON.parse('{"title":"跟做：请求限流、等待提示与 Redis 故障回退","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/rate-limits.md","filePath":"tutorials/rate-limits.md"}'),h={name:"tutorials/rate-limits.md"};function n(p,s,r,l,d,k){return i(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="跟做-请求限流、等待提示与-redis-故障回退" tabindex="-1">跟做：请求限流、等待提示与 Redis 故障回退 <a class="header-anchor" href="#跟做-请求限流、等待提示与-redis-故障回退" aria-label="Permalink to &quot;跟做：请求限流、等待提示与 Redis 故障回退&quot;">​</a></h1><p>运行 <code>just dev</code>，API 默认启用三类固定窗口策略，窗口为 60 秒。同一直接 TCP 对端地址在同一类策略中共享预算：</p><table tabindex="0"><thead><tr><th>策略</th><th>当前请求</th><th style="text-align:right;">Redis 可用</th><th style="text-align:right;">本地回退</th></tr></thead><tbody><tr><td>registration</td><td>POST 注册</td><td style="text-align:right;">20</td><td style="text-align:right;">5</td></tr><tr><td>authentication</td><td>认证类 POST：登录与密码重置；不含注册/退出</td><td style="text-align:right;">60</td><td style="text-align:right;">20</td></tr><tr><td>resource</td><td>其他请求，包括读取、资源写入、退出</td><td style="text-align:right;">600</td><td style="text-align:right;">120</td></tr></tbody></table><p><code>/health/live</code> 与 <code>/health/ready</code> 不消耗预算，避免限流让进程健康探针误报。其他请求放行后仍执行正常 Session、API Key、CSRF 和资源权限检查。</p><h2 id="_1-在页面观察一次限制和恢复" tabindex="-1">1. 在页面观察一次限制和恢复 <a class="header-anchor" href="#_1-在页面观察一次限制和恢复" aria-label="Permalink to &quot;1. 在页面观察一次限制和恢复&quot;">​</a></h2><p>为了快速学习，可在自己的本地 <code>.env</code> 临时设置下面三项，重启 <code>just dev</code>：</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">RATE_LIMIT_AUTHENTICATION</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">2</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">RATE_LIMIT_AUTHENTICATION_FALLBACK</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">1</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">RATE_LIMIT_WINDOW_SECS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">3</span></span></code></pre></div><p>打开登录页，在一个窗口内重复提交错误凭据。达到上限后，响应是统一 429，包含整数秒 <code>Retry-After</code>，正文为 <code>rate_limit.exceeded</code>，<code>error.details.retry_after_seconds</code> 给出同样的等待时长，仍保留 request_id。</p><p>注册/登录页面保留输入并显示倒计时，等待期间不能再次提交；时间到后按钮恢复，但不会自动发出请求。普通资源页面也会展示等待提示，API/Query 层不进行自动乘法重试。体验后恢复默认配置，避免学习时的小预算影响日常开发。</p><p>固定窗口可能在相邻窗口边界允许两批请求，不宣称滑动窗口或均匀速率。生产数值应结合部署规模与实测调整。</p><h2 id="_2-redis-计数与本地计数各做什么" tabindex="-1">2. Redis 计数与本地计数各做什么 <a class="header-anchor" href="#_2-redis-计数与本地计数各做什么" aria-label="Permalink to &quot;2. Redis 计数与本地计数各做什么&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/bab1ba6c8485f53429e3f3c9d1f36aa24a24a567/crates/app/src/modules/rate_limit/mod.rs" target="_blank" rel="noreferrer">Core 限流模块</a>在路由处理器前，根据真实匹配路由与 HTTP 方法选择策略，再对直接对端地址做 hash，生成内部桶标识。地址端口不参与标识，IPv4-mapped IPv6 归一为 IPv4；不信任请求自行声明的 <code>X-Forwarded-For</code>。</p><p>当前代理后的多个用户共享代理地址的预算。可信代理转发需要部署时明确建立边界，不能把任意客户端可伪造的 header 当作身份。缺少 TCP 上下文的自定义组装使用共享 unknown 桶，不因此跳过保护；实际 API 可执行文件已经传入 <code>ConnectInfo&lt;SocketAddr&gt;</code>。</p><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/bab1ba6c8485f53429e3f3c9d1f36aa24a24a567/crates/platform/src/rate_limit.rs" target="_blank" rel="noreferrer">Redis WindowCounter</a>使用一个 Lua 操作完成“读取当前计数 → 判断上限 → 带 TTL 更新”。同一 Redis namespace、策略和窗口的 API 实例共享预算；达到上限后不再增加远端计数。每个操作只尝试一次，有独立的并发和总时限。</p><p>本地也记录每次请求，包括 Redis 正常工作或拒绝时的消耗。Redis 失败时使用这个已消耗的窗口，并按更低的本地上限判断，不能因为切换存储而恢复全额。一次超时的远端命令可能已经执行，本地判断因此可以更保守，不重发它来试图获得“确定结果”。</p><p>本地 map 默认最多 4096 个对端/策略条目，每个新窗口清理过期项。容量满时，新来源共享各策略的保守溢出窗口，不通过淘汰旧条目恢复额度。进程重启会清除本地计数；这种回退面向单机运行，不假装是跨机器的持久配额。</p><h2 id="_3-redis-不可用时仍有限制" tabindex="-1">3. Redis 不可用时仍有限制 <a class="header-anchor" href="#_3-redis-不可用时仍有限制" aria-label="Permalink to &quot;3. Redis 不可用时仍有限制&quot;">​</a></h2><p>停止自己的开发 Redis：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> redis</span></span></code></pre></div><p>已有消耗保留在本地窗口；如果已经超过较低的回退上限，会继续得到 429。下个窗口只恢复本地策略允许的数量。Redis 不可用不会把身份校验改成允许，也不会让 API 无法启动。</p><p>恢复 Redis：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --wait</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> redis</span></span></code></pre></div><p>之后的独立请求会重新建立连接并尝试远端计数。缓存和限流复用 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/bab1ba6c8485f53429e3f3c9d1f36aa24a24a567/crates/platform/src/redis_transport.rs" target="_blank" rel="noreferrer">私有 Redis transport</a> 的连接/超时实现，但各有并发容量，限流不会进入缓存的无限重试或排队。</p><p>默认限流 Redis 操作总预算为 50 ms，包含创建连接、发送和等待回应，满并发容量立即转本地。时间由进程启动时的系统时间与单调经过时间组成；测试注入可控时钟，系统时钟回拨不会让本地窗口倒退。</p><h2 id="_4-配置与观察" tabindex="-1">4. 配置与观察 <a class="header-anchor" href="#_4-配置与观察" aria-label="Permalink to &quot;4. 配置与观察&quot;">​</a></h2><p><a href="./../reference/config">生成配置参考</a>列出 <code>RATE_LIMIT_*</code> 的默认值和范围：窗口、三个正常上限、三个回退上限、本地条目容量、Redis namespace 与操作时限。回退上限必须大于零且不超过对应正常上限。格式或范围错误在监听前失败，只报告字段名。</p><p>使用 Owner/Admin 在浏览器控制台读取：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> fetch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/api/v1/system/rate-limits&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">then</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">response</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> response.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">json</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">());</span></span></code></pre></div><p>结果只包含固定三类策略的允许、拒绝、回退累计计数和本地条目总量，不返回原始地址、桶 hash、邮箱、secret 或每用户标签。请求日志继续使用 route、status、request_id。计量入口本身也受普通资源预算保护。</p><p>运行配置入口默认启用限流。用于聚焦 HTTP 测试的基础 Router 组装默认不启用；自行组装应用时，通过 <code>CoreOptions.limiter</code> 提供明确的实例。标准 API 可执行文件已经使用 <code>RateLimiter::from_env</code>，不是只在测试里演示。</p><h2 id="_5-前端与公开合同" tabindex="-1">5. 前端与公开合同 <a class="header-anchor" href="#_5-前端与公开合同" aria-label="Permalink to &quot;5. 前端与公开合同&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/bab1ba6c8485f53429e3f3c9d1f36aa24a24a567/crates/app/src/http.rs" target="_blank" rel="noreferrer">统一错误工厂</a>构造同一 429 envelope 与 <code>Retry-After</code>。最终组合的 OpenAPI 为受保护的全部操作声明这一响应，生成 SDK 不需要为每个业务重复定义另一种错误。</p><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/bab1ba6c8485f53429e3f3c9d1f36aa24a24a567/packages/views/src/system/rate-limit.tsx" target="_blank" rel="noreferrer">通用等待提示</a>只识别公开错误码和 1–3600 秒范围；不会把任意错误文本当作可执行提示。认证表单的计时器从实际请求失败启动，离开页面清理；倒计时结束仅恢复按钮，没有后台自动重发。业务错误 View 组合相同提示，保持原有的输入和错误处理。内嵌图片与附件链接也保留限流错误，并在等待期间禁用重试；提示使用合法的行内标记。</p><p>登录/注册的成功导航使用随页面观察者存活的回调，避免用户离开后迟到的认证响应把页面拉回。</p><h2 id="_6-验证" tabindex="-1">6. 验证 <a class="header-anchor" href="#_6-验证" aria-label="Permalink to &quot;6. 验证&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rate_limits</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cached_documents</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/rate-limits.test.tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/registration.test.tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/sessions.test.tsx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>真实 Redis/PostgreSQL 的 HTTP 测试使用可控时钟验证阈值、共享窗口和恢复；通过<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/bab1ba6c8485f53429e3f3c9d1f36aa24a24a567/tests/support/redis_gate.rs" target="_blank" rel="noreferrer">共享 TCP 转发夹具</a>断开 Redis，证明旧消耗仍有效且本地额度有限。还验证本地容量溢出、三类策略独立、伪造转发地址无效、放行仍需认证、公开计量与生成合同。</p><p>View 测试使用受控计时器推进等待时间，验证没有自动 POST、表单输入仍在、等待后可明确重试。完成整条旅程后运行一次隔离浏览器配置：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">RATE_LIMIT_AUTHENTICATION</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> RATE_LIMIT_AUTHENTICATION_FALLBACK</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> RATE_LIMIT_WINDOW_SECS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">3</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/e2e.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/e2e/rate-limits.spec.ts</span></span></code></pre></div><p>真实 HTTP 请求消耗认证窗口，浏览器看到 429 和等待按钮，窗口恢复后以真实账号登录。常规开发仍使用较快的 HTTP/View 检查。</p><h2 id="_7-扩展自己的业务" tabindex="-1">7. 扩展自己的业务 <a class="header-anchor" href="#_7-扩展自己的业务" aria-label="Permalink to &quot;7. 扩展自己的业务&quot;">​</a></h2><p>新增普通业务路由自动沿用 resource 策略和统一错误合同，处理器仍负责权限。需要不同策略时，在 Core 的明确分类与配置中增加有限类别，使用稳定标签计量；不要为每个文档、用户或 URL 建立指标标签。</p><p>限流、配置、通用 UI 提示、Redis transport、认证教程和对应 Core 测试在移除知识库后保留。自己的业务无需复制另一个限流器或让 Redis 成为身份与业务事实的唯一来源。</p><hr><p>源码版本：<code>bab1ba6c8485</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/bab1ba6c8485f53429e3f3c9d1f36aa24a24a567/docs/tutorials/17-rate-limits.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,45)])])}const g=a(h,[["render",n]]);export{c as __pageData,g as default};
